ALTER TABLE public.practice_members DROP CONSTRAINT practice_members_check;
CREATE FUNCTION public.validate_practice_member_credentials() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.role='doctor' AND NEW.doctor_id IS NULL AND (NEW.hpcsa_number IS NULL OR length(NEW.hpcsa_number)<2 OR length(NEW.hpcsa_number)>50) THEN RAISE EXCEPTION 'Doctor team members require an HPCSA number'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_practice_member_credentials BEFORE INSERT OR UPDATE ON public.practice_members FOR EACH ROW EXECUTE FUNCTION public.validate_practice_member_credentials();
CREATE OR REPLACE FUNCTION public.add_group_practice_doctor(_practice_id uuid,_email text,_member_role public.group_member_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.doctors%ROWTYPE; p public.profiles%ROWTYPE; result uuid; BEGIN IF NOT(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),_practice_id)) THEN RAISE EXCEPTION 'Practice access denied'; END IF; SELECT * INTO p FROM public.profiles WHERE lower(email)=lower(trim(_email)); IF NOT FOUND THEN RAISE EXCEPTION 'No existing doctor found for that email'; END IF; SELECT * INTO d FROM public.doctors WHERE profile_id=p.id; IF NOT FOUND THEN RAISE EXCEPTION 'No existing doctor found for that email'; END IF; INSERT INTO public.practice_members(practice_id,user_id,doctor_id,full_name,email,role,hpcsa_number,individual_bhf_number,status,member_role) VALUES(_practice_id,p.id,d.id,p.full_name,p.email,'doctor',d.license_number,d.bhf_number,'active',_member_role) ON CONFLICT(practice_id,email) DO UPDATE SET doctor_id=EXCLUDED.doctor_id,member_role=EXCLUDED.member_role,status='active' RETURNING id INTO result; RETURN result; END $$;
COMMENT ON FUNCTION public.is_practice_admin(uuid,uuid) IS 'Intentional authenticated SECURITY DEFINER for nonrecursive RLS; requires protected app role and matching practice assignment.';
COMMENT ON FUNCTION public.group_practice_directory() IS 'Intentional authenticated-only directory; returns active public practice/doctor fields, never banking or private profile data.';
COMMENT ON FUNCTION public.group_practice_members(uuid) IS 'Intentional authenticated SECURITY DEFINER; checks platform admin or scoped practice admin before reading doctor credentials.';
COMMENT ON FUNCTION public.add_group_practice_doctor(uuid,text,public.group_member_role) IS 'Intentional scoped admin mutation; preserves existing doctor practice_id and payouts, never grants owner role.';
COMMENT ON FUNCTION public.assign_group_practice_admin(uuid,text) IS 'Intentional platform-admin-only role assignment; checks server-side role before lookup or write.';